# Sync wrapper example:
from redwood import streaming_sync

for ev in streaming_sync.start_chat(prompt='hello'):
    if ev.type == 'delta':
        print(ev.text, end='')

# Adapter example (user-provided):
class TrimWhitespaceAdapter:
    def map_event(self, event):
        if event.type == 'delta':
            event.text = event.text.rstrip('\n')
        return event
